def compute_pearson(var_values: list, protected_values: list) -> float:
    arr_a = np.array(var_values, dtype=float)
    arr_b = np.array(protected_values, dtype=float)
    # Return 0.0 for zero-variance inputs — correlation is undefined
    if arr_a.std() == 0 or arr_b.std() == 0:
        return 0.0
    return round(float(np.corrcoef(arr_a, arr_b)[1]), 4)
