import hashlib

def compute_dataset_hash(records: list) -> str:
    payload = str(records).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()

def audit_step(tool_version: str):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(data, *args, **kwargs):
            entry = {
                "operation": func.__name__,
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "tool_version": tool_version,
                "input_hash": compute_dataset_hash(data),
                "input_record_count": len(data)
            }
            result = func(data, *args, **kwargs)
            entry["output_hash"] = compute_dataset_hash(result)
            entry["output_record_count"] = len(result)
            write_to_audit_store(entry)
            return result
        return wrapper
    return decorator
