def layer2_zero_width_scan(prompt: str, prompt_hash: str) -> tuple[str, list]:
    """Layer 2 — strip Unicode Cf, Mn, and non-ASCII Zs characters and log each removal."""
    stripped_chars = []
    cleaned = []
    for char in prompt:
        cat = unicodedata.category(char)
        is_non_ascii_space = (cat == "Zs" and char != " ")
        if cat in ("Cf", "Mn") or is_non_ascii_space:
            stripped_chars.append({
                "char":       repr(char),
                "code_point": f"U+{ord(char):04X}",
                "prompt_hash": prompt_hash
            })
        else:
            cleaned.append(char)
    return "".join(cleaned), stripped_chars
