def check2_homoglyph_normalise(prompt: str) -> tuple[str, list]:
    """Check 2 — NFC normalise and replace homoglyphs with ASCII equivalents."""
    normalised    = unicodedata.normalize('NFC', prompt)
    substitutions = []
    cleaned       = []
    for char in normalised:
        if char in HOMOGLYPH_MAP:
            substitutions.append({
                "original":      char,
                "code_point":    f"U+{ord(char):04X}",
                "replaced_with": HOMOGLYPH_MAP[char]
            })
            cleaned.append(HOMOGLYPH_MAP[char])
        else:
            cleaned.append(char)
    return "".join(cleaned), substitutions
