def stage1_structural_check(raw_input: bytes | str) -> tuple[bool, str]:
    """Returns (passed, prompt_string_or_reason).
    On failure the second element is the rejection reason; on pass it is the decoded prompt."""
    if raw_input is None:
        return False, "Prompt is null"
    if isinstance(raw_input, bytes):
        detected = chardet.detect(raw_input)
        try:
            prompt = raw_input.decode(detected["encoding"] or "utf-8", errors="strict")
        except Exception:
            return False, "Prompt encoding is invalid or not decodable as UTF-8"
    else:
        prompt = raw_input
    if not isinstance(prompt, str) or len(prompt.strip()) == 0:
        return False, "Prompt is empty or not a string"
    if len(prompt) > MAX_PROMPT_LENGTH:
        return False, "Prompt exceeds maximum allowed length"
    return True, prompt
