def stage2_semantic_integrity(prompt: str, query_id: str) -> dict:
    """Computes unrecognised token ratio, applies spell-correction in the 10–30% band,
    writes a structured log entry, and returns a typed accept/reject result."""
    tokens = prompt.split()
    if not tokens:
        return {"accepted": False, "reason": "No tokens after splitting"}

    unrec_initial = [t for t in tokens if not is_recognised_token(t)]
    ratio_initial = len(unrec_initial) / len(tokens)

    corrections      = []
    corrected_tokens = tokens[:]

    if UNRECOGNISED_RATIO_CORRECT <= ratio_initial <= UNRECOGNISED_RATIO_REJECT:
        corrected_tokens = []
        for t in tokens:
            if not is_recognised_token(t):
                corrected, was_corrected = spell_correct_token(t)
                if was_corrected:
                    corrections.append({"original": t, "corrected": corrected})
                corrected_tokens.append(corrected)
            else:
                corrected_tokens.append(t)

    unrec_final = [t for t in corrected_tokens if not is_recognised_token(t)]
    ratio_final = len(unrec_final) / len(corrected_tokens)
    prompt_hash = hashlib.sha256(" ".join(tokens).encode()).hexdigest()

    log_entry = {
        "query_id":                    query_id,
        "checked_at":                  datetime.now(timezone.utc).isoformat(),
        "unrecognised_ratio_initial":  round(ratio_initial, 4),
        "unrecognised_ratio_final":    round(ratio_final,   4),
        "prompt_hash":                 prompt_hash,
        "corrections":                 corrections
    }
    write_audit_log({**log_entry, "event": "SEMANTIC_INTEGRITY_CHECK"})

    if ratio_final > UNRECOGNISED_RATIO_REJECT:
        return {"accepted": False, "reason": "Unrecognised token ratio above 30%", **log_entry}
    return {"accepted": True, "sanitised_prompt": " ".join(corrected_tokens), **log_entry}
